-- Satsuei: Hyprland visual layer. Generated by rice-render from palette.toml
-- (and the plate's overlay from satsuei-wall). Loaded from hyprland.lua via
-- ~/.local/share/rice/active/hypr.lua.

-- Windows are cels laid over the plate: glass (kitty at 0.72), rounded 16,
-- edged by a line running from the plate's accent into its second accent,
-- with a large soft shadow. Workspaces are episodes and slide like a cut.

hl.config({
    general = {
        gaps_in     = {{ shape.gaps_in }},
        gaps_out    = {{ shape.gaps_out }},
        border_size = {{ shape.border }},
    },

    decoration = {
        rounding         = {{ shape.window }},
        rounding_power   = {{ shape.rounding_power }},
        active_opacity   = 1.0,
        dim_inactive     = false,

        -- the glass: the plate behind a window, softened
        blur = {
            enabled           = true,
            size              = 8,
            passes            = 3,
            new_optimizations = true,
            noise             = 0.015,
            contrast          = 1.0,
            popups            = true,
            xray              = false,
        },

        shadow = {
            enabled      = true,
            render_power = 2,
        },
    },

    group = {
        groupbar = {
            enabled           = true,
            height            = 18,
            indicator_height  = 0,
            gradients         = true,
            rounding          = {{ shape.chip }},
            gradient_rounding = {{ shape.chip }},
            round_only_edges  = false,
            gradient_round_only_edges = false,
            font_family       = "{{ fonts.ui }}",
            font_size         = 11,
            font_weight_active   = {{ fonts.weight_strong }},
            font_weight_inactive = {{ fonts.weight }},
        },
    },

    animations = { enabled = true },
})

---------------------------------------------------------------------------
-- Motion: arrivals overshoot a touch, episodes slide like a cut
---------------------------------------------------------------------------
hl.curve("bloom",  { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} },  { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.curve("settle", { type = "bezier", points = { { {{ motion.settle.0 }}, {{ motion.settle.1 }} }, { {{ motion.settle.2 }}, {{ motion.settle.3 }} } } })
hl.curve("cut",    { type = "bezier", points = { { {{ motion.sink.0 }}, {{ motion.sink.1 }} },   { {{ motion.sink.2 }}, {{ motion.sink.3 }} } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })

-- speed is in deciseconds
hl.animation({ leaf = "windowsIn",    enabled = true, speed = {{ motion.open | div(100) }},       bezier = "bloom",  style = "popin 92%" })
hl.animation({ leaf = "windowsOut",   enabled = true, speed = {{ motion.close | div(100) }},      bezier = "cut",    style = "popin 94%" })
hl.animation({ leaf = "windowsMove",  enabled = true, speed = {{ motion.move | div(100) }},       bezier = "bloom" })
hl.animation({ leaf = "fadeIn",       enabled = true, speed = {{ motion.open | div(100) }},       bezier = "bloom" })
hl.animation({ leaf = "fadeOut",      enabled = true, speed = {{ motion.close | div(100) }},      bezier = "cut" })
hl.animation({ leaf = "fadeSwitch",   enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "bloom" })
hl.animation({ leaf = "border",       enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "bloom" })
hl.animation({ leaf = "borderangle",  enabled = true, speed = {{ motion.border_loop | div(100) | min(100) }}, bezier = "linear", style = "loop" })
-- episodes: a horizontal slide, 0.6 s, the mock's cut (.65,0,.25,1)
hl.animation({ leaf = "workspaces",   enabled = true, speed = {{ motion.workspace | div(100) }},  bezier = "cut",    style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = {{ motion.scratchpad | div(100) }}, bezier = "bloom", style = "slidevert" })
-- Quickshell animates its own panels; Hyprland only fades unknown layers
hl.animation({ leaf = "layers",       enabled = true, speed = 3, bezier = "bloom", style = "fade" })

---------------------------------------------------------------------------
-- Styling the base layer's window tags
---------------------------------------------------------------------------
-- forced opaque: browsers, video, images, editors, games
hl.window_rule({ name = "satsuei-opaque", match = { tag = "opaque" }, opacity = "1.0 override 1.0 override" })
-- glassy: files, music, system tools are frosted glass over the plate
-- (Hyprland's blur behind them); untagged apps (browsers, Electron) stay solid
hl.window_rule({ name = "satsuei-glassy", match = { tag = "glassy" }, opacity = "{{ opacity.active }} override {{ opacity.inactive }} override" })
-- terminals frost themselves (kitty's background at {{ opacity.terminal }}), so the window
-- stays whole and the text keeps its full strength
hl.window_rule({
    name = "satsuei-terminal", match = { class = "^(kitty|foot|Alacritty|com.mitchellh.ghostty|org.wezfurlong.wezterm)$" },
    opacity = "1.0 override 1.0 override",
})
-- floating dialogs: the popups' rounding (Hyprland allows at most 20)
hl.window_rule({ name = "satsuei-dialog", match = { tag = "dialog" }, rounding = {{ shape.popup }} })
-- picture-in-picture: no border
hl.window_rule({ name = "satsuei-pip", match = { tag = "pip" }, border_size = 0, no_shadow = true })
-- fullscreen: no border or rounding
hl.window_rule({ name = "satsuei-fullscreen", match = { fullscreen = true }, border_size = 0, rounding = 0 })
-- games: no animations, blur or shadow; always opaque
hl.window_rule({
    name = "satsuei-game", match = { tag = "game" },
    no_anim = true, no_blur = true, no_shadow = true, opacity = "1.0 override 1.0 override",
})

---------------------------------------------------------------------------
-- Quickshell surfaces (every one is satsuei-*): the glass blurs the plate
-- behind it, and pixels under 0.3 alpha (shadows, the subtitles' outline)
-- don't. The plate itself, the eyecatch's text and the mascot aren't glass,
-- and a blur behind a full-screen layer would cost a pass a frame.
---------------------------------------------------------------------------
hl.layer_rule({
    name = "satsuei-glass",
    match = { namespace = "^satsuei-(bar|center|studio|subs|walls|cast|launcher|osd|power|toast|keys|stats|deskcard|deskpanel)$" },
    blur = true, ignore_alpha = 0.3, no_anim = true,
})
hl.layer_rule({ name = "satsuei-still", match = { namespace = "^satsuei-(plate|eyecatch|mascot)$" }, no_anim = true })

---------------------------------------------------------------------------
-- The colours: borders, shadows (beside this file in build/dark/)
---------------------------------------------------------------------------
local here = debug.getinfo(1, "S").source:match("^@(.*/)") or
    ((os.getenv("XDG_DATA_HOME") or (os.getenv("HOME") .. "/.local/share")) .. "/rice/active/")
dofile(here .. "hypr-mode.lua")
